package app.ember.airreceiver.service

/**
 * AirReceiverService stub for JVM test compilation.
 *
 * The real AirReceiverService extends android.app.Service and depends on
 * NotificationCompat (AndroidX) and the R resource class (generated by AGP),
 * neither of which are available in the standalone JVM test runner.
 *
 * This stub provides only the companion object constants that are needed by
 * ServiceController (at compile time) and ServiceControllerTest / AirReceiverServiceTest
 * (at test time). No Android lifecycle methods are present.
 */
class AirReceiverService {
    companion object {
        const val ACTION_START   = "app.ember.airreceiver.action.START"
        const val ACTION_STOP    = "app.ember.airreceiver.action.STOP"
        const val ACTION_RESTART = "app.ember.airreceiver.action.RESTART"
        const val ACTION_SET_RECEIVER = "app.ember.airreceiver.action.SET_RECEIVER"
        const val EXTRA_PROTOCOL = "protocol"
        const val EXTRA_ENABLED = "enabled"
        const val NOTIFICATION_ID = 1
        const val CHANNEL_ID     = "airreceiver_service"
    }
}
